#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=11

banner "IBKR execution service: account, alerts and hosting setup"

# ── 1. Local secrets ──────────────────────────────────────────────────────
stage "Local: HMAC secrets and fixed settings"
say "The bot and the admin endpoints each sign requests with their own secret."
say "They are generated here, never typed, and reused on re-runs."
gen() {
  if command -v openssl >/dev/null 2>&1; then openssl rand -hex 32
  else python3 -c 'import secrets; print(secrets.token_hex(32))'; fi
}
if [[ -f "$ENV_FILE" ]] && grep -qE '^HMAC_BOT_SECRET=' "$ENV_FILE"; then
  note "HMAC_BOT_SECRET already in $ENV_FILE, keeping it"
else
  write_env HMAC_BOT_SECRET "$(gen)"
fi
if [[ -f "$ENV_FILE" ]] && grep -qE '^HMAC_ADMIN_SECRET=' "$ENV_FILE"; then
  note "HMAC_ADMIN_SECRET already in $ENV_FILE, keeping it"
else
  write_env HMAC_ADMIN_SECRET "$(gen)"
fi
write_env TRADING_MODE "paper"
write_env IB_HOST "127.0.0.1"
write_env IB_PORT "4002"
note "TRADING_MODE stays 'paper'. Live needs CONFIRM_LIVE=yes set by hand, never by this wizard."
pause

# ── 2. IBKR bot user ──────────────────────────────────────────────────────
stage "IBKR: add the bot username (trading rights only)"
say "The service logs in as a second username so your own app login never drops it,"
say "and so a leaked credential cannot move money."
open_url "https://www.interactivebrokers.com/sso/Login"
step "Log in as the account owner (not the bot)."
step "Top-right user menu → Settings → Account Settings → Users & Access Rights."
step "Click the + (Add User). Fill in the bot's details and choose a username."
step "On Access Rights: enable Trading only. Leave off: Funding, Withdrawals/Transfers,"
step "  Account Configuration, Trading Permissions, Users & Access Rights, Reports."
warn "IBKR may take about a business day to activate the user. The next stages need it active."
ask IB_LIVE_USERNAME "Bot username you created:"
write_env IB_LIVE_USERNAME "$IB_LIVE_USERNAME"
note "Stored for reference only; the service never logs in to the live account in paper mode."
pause

# ── 3. Bot user first login + IB Key ──────────────────────────────────────
stage "IBKR: bot user first login and two-factor (IB Key)"
say "IBKR requires two-factor on every username. IB Key in the IBKR Mobile app gives a"
say "push prompt the service can wait on; it never retries logins in a loop."
step "Open the IBKR email for the new user, log in with the temporary password, set a new one."
step "Install IBKR Mobile on a phone you will have during trading hours."
step "In the app: Two-Factor Authentication → enrol IB Key for the BOT username."
step "Log out and in again once to confirm the push prompt arrives."
note "Keep the bot's password in a password manager; it is asked for in the next stage."
pause "Bot user logs in with IB Key? Press Enter."

# ── 4. Paper account for the bot user ─────────────────────────────────────
stage "IBKR: paper trading account (DU…) for the bot user"
say "IBC logs the gateway into the PAPER username; the service refuses to start if the"
say "connected account id does not start with DU while TRADING_MODE is paper."
open_url "https://www.interactivebrokers.com/sso/Login"
step "Log in as the BOT user → Settings → Account Settings → Paper Trading Account."
step "If no paper account exists yet, request one; note the paper username shown."
step "Use 'Reset Paper Trading Password' and set a password you record."
step "Turn ON 'Share real-time market data with paper trading account'."
warn "If the bot user has no Paper Trading Account page, the paper account may belong to"
warn "the primary user only. Then use the primary user's paper credentials for the paper phase."
ask TWS_USERID "Paper username:"
ask_secret TWS_PASSWORD "Paper password (hidden):"
step "Log in to the Client Portal with the paper username once; the account id (DU…) is shown"
step "  in the top bar / Portfolio page."
ask IB_ACCOUNT_ID "Paper account id (starts with DU):"
if [[ "$IB_ACCOUNT_ID" != DU* ]]; then
  warn "'$IB_ACCOUNT_ID' does not start with DU. Paper ids do; check you copied the paper account."
  confirm "Keep it anyway?" || ask IB_ACCOUNT_ID "Paper account id (starts with DU):"
fi
write_env TWS_USERID "$TWS_USERID"
write_env TWS_PASSWORD "$TWS_PASSWORD"
write_env IB_ACCOUNT_ID "$IB_ACCOUNT_ID"
note "TWS_USERID / TWS_PASSWORD / TRADING_MODE are the names the common IB Gateway + IBC Docker images read."
pause

# ── 5. Market data status ─────────────────────────────────────────────────
stage "IBKR: market data subscriber status"
say "Paper runs on the free real-time non-consolidated quotes. Before live, the bot user"
say "needs the Value Bundle and the Add-On Streaming Bundle. Today we only confirm status."
step "Logged in as the BOT user → Settings → User Settings → Market Data Subscriptions."
step "Confirm 'Market Data Subscriber Status' reads Non-Professional."
step "Do NOT subscribe to paid bundles yet; that is a live-mode step."
note "Public prices: https://www.interactivebrokers.com/en/pricing/market-data-pricing.php"
pause "Status is Non-Professional? Press Enter."

# ── 6. PDT question ───────────────────────────────────────────────────────
stage "IBKR: ask whether PDT limits apply to this account"
say "pdt_guard stays ON (3 day trades per 5 business days under \$25k) until IBKR"
say "confirms in writing that the rule does not apply to this No Borrow Margin account."
step "Client Portal → Help → Secure Message Center → Compose."
step "Category: Account Services. Ask: 'Does the Pattern Day Trader rule apply to my"
step "  No Borrow Margin account after FINRA's June 4 2026 change? Where do I see day trades left?'"
step "Also note the 'Day Trades Left' figure shown in the Client Portal account summary."
pause "Message sent? Press Enter."

# ── 7. Local IB Gateway ───────────────────────────────────────────────────
stage "Local: install IB Gateway and set its API settings"
say "Build step 6 runs the service locally against the paper gateway on port 4002."
open_url "https://www.interactivebrokers.com/en/trading/ibgateway-stable.php"
step "Download and install IB Gateway (stable). Start it, choose Paper Trading, log in"
step "  with the paper username. Approve the IB Key prompt."
step "Configure → Settings → API → Settings:"
step "  ✓ Enable ActiveX and Socket Clients    ✗ Read-Only API"
step "  Socket port: 4002                       ✓ Allow connections from localhost only"
step "  Trusted IPs: 127.0.0.1"
step "Configure → Settings → API → Precautions: tick 'Bypass Order Precautions for API Orders'."
note "The service still logs every warning IBKR sends and cancels on any type not allow-listed."
pause "Gateway logged in with those settings? Press Enter."

# ── 8. Slack webhook ──────────────────────────────────────────────────────
stage "Slack: incoming webhook to a private channel"
say "Every failure that a human must see goes here, independent of the gateway being up."
step "In Slack, create a private channel (e.g. #ibkr-alerts) if you do not have one."
open_url "https://api.slack.com/apps?new_app=1"
step "Create New App → From scratch → name it, pick your workspace."
step "Features → Incoming Webhooks → toggle On → Add New Webhook to Workspace."
step "Choose the private channel → Allow → copy the Webhook URL (https://hooks.slack.com/services/…)."
ask_secret SLACK_WEBHOOK_URL "Paste the webhook URL (hidden):"
write_env SLACK_WEBHOOK_URL "$SLACK_WEBHOOK_URL"
if confirm "Send a test message to the channel now?"; then
  if curl -sS -X POST -H 'Content-type: application/json' \
       --data '{"text":"IBKR execution service: alert channel wired up (setup wizard)."}' \
       "$SLACK_WEBHOOK_URL" >/dev/null; then
    printf '  %s✓ sent%s check the channel\n' "$GREEN" "$RESET"
  else
    warn "the webhook call failed; re-check the URL"
  fi
fi
pause

# ── 9. Render Postgres ────────────────────────────────────────────────────
stage "Render: Postgres in Virginia (US East)"
say "Signals, decisions, orders, fills and daily P&L live here. Same region as the worker."
open_url "https://dashboard.render.com"
step "New + → Postgres. Name: ibkr-exec-db. Region: Virginia (US East). PostgreSQL 16+."
step "Pick a plan with persistent storage (the free tier expires), then Create Database."
step "On the database page → Connections: copy the EXTERNAL Database URL for local dev."
ask_secret DATABASE_URL "Paste the External Database URL (hidden):"
write_env DATABASE_URL "$DATABASE_URL"
note "On the worker, use the INTERNAL URL instead (private network, no TLS hop). Next stage."
pause

# ── 10. Render Background Worker ─────────────────────────────────────────
stage "Render: Docker Background Worker in Virginia"
say "One container runs IB Gateway + IBC + the service, so port 4002 never leaves localhost."
if confirm "Has the repo with its Dockerfile been pushed yet?"; then
  open_url "https://dashboard.render.com"
  step "New + → Background Worker → connect this GitHub repo."
  step "Region: Virginia (US East). Runtime: Docker. Instance: Standard (2 GB) or larger."
  step "Environment → 'Add from .env': paste the contents of $ENV_FILE, then:"
  step "  replace DATABASE_URL with the Postgres INTERNAL URL,"
  step "  make sure CONFIRM_LIVE is absent and TRADING_MODE=paper."
  step "Deploy outside market hours; the first login needs an IB Key approval on your phone."
  step "On the worker page, find 'Outbound IP addresses' (Settings or the Connect menu)."
  ask RENDER_OUTBOUND_IPS "Paste the outbound IPs, comma-separated:"
  write_env RENDER_OUTBOUND_IPS "$RENDER_OUTBOUND_IPS"
else
  SKIPPED+=("Render Background Worker (re-run this wizard after pushing the Dockerfile)")
  SKIPPED+=("IBKR IP restriction for the bot user (needs the Render outbound IPs)")
  note "Skipping the worker and the IP restriction. Re-run after build step 7 is ready."
fi
pause

# ── 11. IBKR IP restriction ───────────────────────────────────────────────
stage "IBKR: restrict the bot user to Render's outbound IPs"
if [[ -n "${RENDER_OUTBOUND_IPS:-}" ]]; then
  say "With a fixed egress, a stolen bot password is useless from anywhere else."
  open_url "https://www.interactivebrokers.com/sso/Login"
  step "Log in as the BOT user → Settings → User Settings → Security → IP Restrictions."
  step "Add each address: $RENDER_OUTBOUND_IPS"
  warn "Your laptop will no longer be able to log in as the bot user. Use the owner login for the portal."
  warn "Check the exact menu name; IBKR moves settings around. Ask support if it is not under Security."
  pause "Restriction saved? Press Enter."
else
  note "No Render outbound IPs captured, so nothing to restrict yet."
  pause
fi

finish
}

run_wizard "$@"; exit
